import z3
from itertools import combinations

n = 23
min_deg = 3
max_deg = 6

edges = {}
for i in range(n):
    for j in range(i+1, n):
        edges[(i, j)] = z3.Bool(f"e_{i}_{j}")

s = z3.Solver()

# Degree constraints
for v in range(n):
    incident = [edges[(min(v, u), max(v, u))] for u in range(n) if u != v]
    s.add(z3.Sum([z3.If(e, 1, 0) for e in incident]) >= min_deg)
    s.add(z3.Sum([z3.If(e, 1, 0) for e in incident]) <= max_deg)

# No triangles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            s.add(z3.Not(z3.And(edges[(i,j)], edges[(i,k)], edges[(j,k)])))

# No 4-cycles
for i in range(n):
    for j in range(i+1, n):
        for k in range(n):
            if k == i or k == j:
                continue
            for l in range(k+1, n):
                if l == i or l == j:
                    continue
                a, b = min(i, k), max(i, k)
                c, d = min(k, j), max(k, j)
                e, f = min(j, l), max(j, l)
                g, h = min(l, i), max(l, i)
                s.add(z3.Not(z3.And(edges[(a,b)], edges[(c,d)], edges[(e,f)], edges[(g,h)])))

print("Base constraints added. Starting lazy 5-cycle elimination...")

# Lazy approach for 5-cycles
max_iterations = 50
for iteration in range(max_iterations):
    print(f"Iteration {iteration}: checking...")
    result = s.check()
    if result == z3.unsat:
        print("UNSAT!")
        break

    model = s.model()

    # Extract the graph
    adj = {i: set() for i in range(n)}
    for (i, j), var in edges.items():
        if z3.is_true(model.eval(var)):
            adj[i].add(j)
            adj[j].add(i)

    # Check for 5-cycles
    found_5cycle = False
    for v0 in range(n):
        if found_5cycle:
            break
        for v1 in adj[v0]:
            if v1 <= v0:
                continue
            for v2 in adj[v1]:
                if v2 in (v0, v1):
                    continue
                for v3 in adj[v2]:
                    if v3 in (v0, v1, v2):
                        continue
                    for v4 in adj[v3]:
                        if v4 in (v0, v1, v2, v3):
                            continue
                        if v0 in adj[v4]:
                            # Found a 5-cycle: v0-v1-v2-v3-v4-v0
                            # Add constraint to break it
                            cycle = [v0, v1, v2, v3, v4]
                            # Normalize
                            e_vars = []
                            for a_idx in range(5):
                                b_idx = (a_idx + 1) % 5
                                a, b = cycle[a_idx], cycle[b_idx]
                                e_vars.append(edges[(min(a,b), max(a,b))])
                            s.add(z3.Not(z3.And(*e_vars)))
                            found_5cycle = True
                            print(f"  Found 5-cycle: {cycle}, adding constraint")
                            break

    if not found_5cycle:
        print("No 5-cycles found! Graph is valid.")
        # Print the graph
        edge_list = []
        for (i, j), var in edges.items():
            if z3.is_true(model.eval(var)):
                edge_list.append((i, j))
        print(f"Edges: {edge_list}")
        print(f"Number of edges: {len(edge_list)}")
        for v in range(n):
            deg = len(adj[v])
            print(f"  Vertex {v}: degree {deg}, neighbors: {sorted(adj[v])}")
        break

if result == z3.sat and not found_5cycle:
    print("SUCCESS!")
else:
    print("Failed to find solution within iterations")

